lines += ['### جرد الجداول والحقول', '', 'يعرض الجدول التالي كل جدول كما ظهر في `sqlite_master`، مع جميع الحقول ونوع كل حقل. تشير `PK` إلى المفتاح الأساسي، وتشير `FK` إلى أن الحقل جزء من مفتاح أجنبي معلن في SQLite.', '']
for t in D['tables']:
    lines += [f'#### `{t["name"]}` — {t["row_count"]:,} سجل', '', '| الحقل | النوع | PK | FK | إلزامي |', '|---|---|---:|---:|---:|']
    fks={(f['from'],f['table'],f['to']) for f in t['foreign_keys']}
    for c in t['columns']:
        refs=[f for f in t['foreign_keys'] if f['from']==c['name']]
        ref=', '.join(f'`{f["table"]}.{f["to"]}`' for f in refs) or '—'
        lines.append(f'| `{c["name"]}` | `{c["type"]}` | {"نعم" if c["pk"] else "لا"} | {ref} | {"نعم" if c["notnull"] else "لا"} |')
    lines.append('')
lines += ['### العلاقات الرسمية Cardinality', '', 'العلاقات التالية مستخرجة من `PRAGMA foreign_key_list` وقيود الفهارس الفريدة. العلاقة تكون **One-to-One** عندما يكون الحقل الأجنبي فريدًا منفردًا، وتكون **One-to-Many** في غير ذلك. جداول الربط ذات المفتاح الفريد المركب تمثل **Many-to-Many** بين الكيانين المرتبطين.', '']
for t in D['tables']:
    for f in t['foreign_keys']:
        uniq=any(ix['unique'] and [x['name'] for x in ix['columns']]==[f['from']] for ix in t['indexes'])
        card='One-to-One' if uniq else 'One-to-Many (الأب ← التابع)'
        lines.append(f'- `{f["table"]}.{f["to"]}` ← `{t["name"]}.{f["from"]}` — **{card}**؛ `ON DELETE {f["on_delete"]}`, `ON UPDATE {f["on_update"]}`.')
lines += ['', '### Many-to-Many الرسمية', '']
for t in D['tables']:
    for ix in t['indexes']:
        if ix['unique'] and len(ix['columns'])==2:
            cols=[x['name'] for x in ix['columns']]
            fks=[f for f in t['foreign_keys'] if f['from'] in cols]
            if len(fks)==2:
                lines.append(f'- `{t["name"]}` يربط `{fks[0]["table"]}` و`{fks[1]["table"]}` عبر القيد الفريد المركب `{", ".join(cols)}`.')
lines += ['', '### القيود والفهارس', '']
lines += ['تتضمن البنية قيود `NOT NULL`، ومفاتيح أساسية `AUTOINCREMENT`، وقيود `UNIQUE` على بعض الحقول مثل البريد الإلكتروني واسم المستخدم وأكواد المحافظ وأنواع المستندات، وقيود `CHECK` على القيم غير السالبة في سنوات الخبرة ونطاق الخدمة وعدد الطلبات وبعض النسب. كما تتضمن فهارس مفردة ومركبة لتحسين البحث حسب الحالة والمستخدم ومقدم الخدمة والتاريخ. التفاصيل الكاملة القابلة للتدقيق موجودة في `schema_summary.txt` داخل المستودع.', '']
